const response = $input.first().json;
const hits = response.hits?.hits ?? [];

if (hits.length === 0) {
  return [];
}

return hits.map((hit) => {
  const source = hit._source ?? {};
  const parameters = source['kibana.alert.rule.parameters'] ?? {};

  const ruleMetadata = {};
  const evidence = {};

  for (const [key, value] of Object.entries(source)) {
    if (key.startsWith('kibana.alert.rule.')) {
      ruleMetadata[key] = value;
    } else if (!key.startsWith('kibana.alert.')) {
      evidence[key] = value;
    }
  }

  return {
    json: {
      alert: {
        id: hit._id,
        index: hit._index,
        timestamp: source['@timestamp'] ?? null,
        status: source['kibana.alert.status'] ?? null,
        workflow_status: source['kibana.alert.workflow_status'] ?? null,
        reason: source['kibana.alert.reason'] ?? null,
        url: source['kibana.alert.url'] ?? null
      },
      rule: {
        id: source['kibana.alert.rule.rule_id'] ?? parameters.rule_id ?? null,
        uuid: source['kibana.alert.rule.uuid'] ?? null,
        name: source['kibana.alert.rule.name'] ?? null,
        description: source['kibana.alert.rule.description'] ?? parameters.description ?? null,
        severity: source['kibana.alert.rule.severity'] ?? parameters.severity ?? null,
        risk_score: source['kibana.alert.rule.risk_score'] ?? parameters.risk_score ?? null,
        tags: source['kibana.alert.rule.tags'] ?? [],
        interval: source['kibana.alert.rule.interval'] ?? null,
        from: source['kibana.alert.rule.from'] ?? parameters.from ?? null,
        to: source['kibana.alert.rule.to'] ?? parameters.to ?? null,
        type: parameters.type ?? null,
        language: parameters.language ?? null,
        esql_query: parameters.query ?? null,
        false_positives: parameters.false_positives ?? [],
        threat: parameters.threat ?? [],
        references: parameters.references ?? [],
        parameters,
        metadata: ruleMetadata
      },
      execution: {
        uuid: source['kibana.alert.rule.execution.uuid'] ?? null,
        timestamp: source['kibana.alert.rule.execution.timestamp'] ?? null,
        type: source['kibana.alert.rule.execution.type'] ?? null
      },
      evidence
    },
    pairedItem: { item: 0 }
  };
});

const alertItems = $items('Extract Alert Details', 0, 0);
const timingItems = $input.all();

return timingItems.map((item, index) => {
  const details = alertItems[index]?.json;
  if (!details) {
    throw new Error(`No matching alert details for timing item ${index}`);
  }

  const timing = item.json.hits?.hits?.[0]?._source ?? null;
  const durationNs = timing?.event?.duration == null ? null : Number(timing.event.duration);
  const scheduleDelayNs = timing?.kibana?.task?.schedule_delay == null
    ? null
    : Number(timing.kibana.task.schedule_delay);

  return {
    json: {
      ...details,
      execution: {
        ...details.execution,
        timing_found: timing !== null,
        scheduled_at: timing?.kibana?.task?.scheduled ?? null,
        started_at: timing?.event?.start ?? null,
        ended_at: timing?.event?.end ?? timing?.['@timestamp'] ?? null,
        outcome: timing?.event?.outcome ?? null,
        status: timing?.kibana?.alerting?.status ?? null,
        revision: timing?.kibana?.alert?.rule?.revision ?? null,
        event_duration_ms: Number.isFinite(durationNs) ? durationNs / 1000000 : null,
        schedule_delay_ms: Number.isFinite(scheduleDelayNs) ? scheduleDelayNs / 1000000 : null,
        metrics: timing?.kibana?.alert?.rule?.execution?.metrics ?? {}
      }
    },
    pairedItem: { item: index }
  };
});

const payloadItems = $items('Build Investigation Payload', 0, 0);

return $input.all().map((item, index) => {
  const payload = payloadItems[index]?.json;
  if (!payload) {
    throw new Error(`No source investigation payload for AI result ${index}`);
  }

  let triage = item.json.output;
  if (typeof triage === 'string') {
    try {
      triage = JSON.parse(triage);
    } catch (error) {
      throw new Error(`AI output is not valid JSON for alert ${payload.alert.id}: ${error.message}`);
    }
  }

  if (!triage || typeof triage !== 'object' || Array.isArray(triage)) {
    throw new Error(`AI output is not an object for alert ${payload.alert.id}`);
  }

  return {
    json: {
      schema_version: '1.0',
      generated_at: new Date().toISOString(),
      alert: payload.alert,
      rule: payload.rule,
      execution: payload.execution,
      evidence: payload.evidence,
      triage
    },
    pairedItem: { item: index }
  };
});

const investigations = $input.all().map((item) => item.json);

const cell = (value) => String(value ?? '')
  .replace(/\|/g, '\\|')
  .replace(/\r?\n/g, '<br>');

const header = '| Alert | Time | Rule | Severity | Risk | Verdict | Priority | Confidence | Summary | Suggested status |';
const divider = '|---|---|---|---|---:|---|---|---:|---|---|';
const rows = investigations.map((result) => {
  const confidence = Number(result.triage.confidence);
  const confidenceText = Number.isFinite(confidence)
    ? `${Math.round(confidence * 100)}%`
    : '';

  return `| ${cell(result.alert.id)} | ${cell(result.alert.timestamp)} | ${cell(result.rule.name)} | ${cell(result.rule.severity)} | ${cell(result.rule.risk_score)} | ${cell(result.triage.verdict)} | ${cell(result.triage.priority)} | ${cell(confidenceText)} | ${cell(result.triage.summary)} | ${cell(result.triage.workflow_status_recommendation)} |`;
});

return [{
  json: {
    count: investigations.length,
    investigations,
    markdown_table: [header, divider, ...rows].join('\n')
  }
}];
